<div class="top"><h1><?= e($e['title']) ?></h1><a class="btn btn-a" href="/admin/<?= e($path) ?>/nouveau"><?= ic('plus') ?> Ajouter</a></div><?php if (!empty($e['note'])): ?><div class="alert a-info"><?= e($e['note']) ?></div><?php endif; ?>
<div class="tbl-wrap"><table class="tbl"><thead><tr><?php foreach ($e['cols'] as $c): ?><th><?= e(is_array($c) ? $c[0] : $c) ?></th><?php endforeach; ?><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><?php foreach ($e['cols'] as $k => $c): $v = $r[$k] ?? ''; $v = is_array($c) ? $c[1]($v) : $v; ?><td><?= e(mb_strimwidth((string) $v, 0, 70, '…')) ?></td><?php endforeach; ?><td style="white-space:nowrap"><a class="btn btn-p btn-sm" href="/admin/<?= e($path) ?>/<?= (int) $r['id'] ?>">Modifier</a> <form method="post" action="/admin/<?= e($path) ?>/<?= (int) $r['id'] ?>/supprimer" style="display:inline" data-confirm="Supprimer cet élément ?"><?= csrf_field() ?><button class="btn btn-d btn-sm" aria-label="Supprimer"><?= ic('trash') ?></button></form></td></tr><?php endforeach; ?>
